import { useEffect, useState } from 'react'

// Loads secondary data after the page renders, so a slow or failing request
// never holds the page up. Null until it loads for the current `key`, and
// when it fails.
export function useDeferred<T>(key: string, load: () => Promise<T>) {
  const [state, setState] = useState<{ key: string; data: T } | null>(null)
  useEffect(() => {
    let current = true
    load()
      .then((data) => current && setState({ key, data }))
      .catch(() => {})
    return () => {
      current = false
    }
    // `load` is a new closure every render; `key` names what it loads.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [key])
  return state?.key === key ? state.data : null
}
import { Link } from '@tanstack/react-router'
import { Check, ExternalLink, Store } from 'lucide-react'

import { BookCover } from '#/components/book-cover'
import type { DiscoverBook } from '#/lib/discover-functions'

// A scrolling row (or a grid) of Hardcover books. A book in the library opens its page;
// otherwise admins search the Market for it and users open it on Hardcover.
export function DiscoverRow<T extends DiscoverBook>({
  title,
  books,
  admin,
  detail,
  grid,
}: {
  title: string
  books: T[]
  admin: boolean
  detail?: (book: T) => string
  grid?: boolean
}) {
  if (books.length === 0) return null
  return (
    <section className="min-w-0">
      <h2 className="mb-3 text-lg font-semibold">{title}</h2>
      <ul
        className={
          grid
            ? 'grid grid-cols-2 gap-x-4 gap-y-6 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6'
            : '-mx-4 flex snap-x scroll-px-4 gap-4 overflow-x-auto px-4 pb-2'
        }
      >
        {books.map((book) => (
          <li
            key={book.id}
            className={grid ? undefined : 'w-28 shrink-0 snap-start sm:w-32'}
          >
            <DiscoverCard book={book} admin={admin} detail={detail} />
          </li>
        ))}
      </ul>
    </section>
  )
}

function DiscoverCard<T extends DiscoverBook>({
  book,
  admin,
  detail,
}: {
  book: T
  admin: boolean
  detail?: (book: T) => string
}) {
  const body = (
    <>
      <BookCover
        {...book}
        className="transition-shadow group-hover:shadow-md"
      />
      <p className="mt-2 line-clamp-2 text-sm leading-snug font-medium">
        {book.title}
      </p>
      <p className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground">
        {book.libraryId ? (
          <>
            <Check className="size-3 shrink-0" /> In library
          </>
        ) : admin ? (
          <>
            <Store className="size-3 shrink-0" /> Find in Market
          </>
        ) : (
          <>
            <ExternalLink className="size-3 shrink-0" /> Hardcover
          </>
        )}
        {detail && <span className="ml-auto">{detail(book)}</span>}
      </p>
    </>
  )
  if (book.libraryId) {
    return (
      <Link
        to="/books/$bookId"
        params={{ bookId: book.libraryId }}
        className="group block"
      >
        {body}
      </Link>
    )
  }
  if (admin) {
    return (
      <Link
        to="/market"
        search={{ q: [book.title, book.authors[0]].filter(Boolean).join(' ') }}
        className="group block"
      >
        {body}
      </Link>
    )
  }
  return (
    <a href={book.url} target="_blank" rel="noreferrer" className="group block">
      {body}
    </a>
  )
}
import { Fragment, useState } from 'react'
import {
  Link,
  createFileRoute,
  notFound,
  useRouter,
} from '@tanstack/react-router'
import { Download, RotateCcw, SearchCheck, Star, Trash2 } from 'lucide-react'

import { BookCover } from '#/components/book-cover'
import { DiscoverRow } from '#/components/discover-row'
import { MatchDialog } from '#/components/match-dialog'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '#/components/ui/alert-dialog'
import { Button } from '#/components/ui/button'
import { useDeferred } from '#/hooks/use-deferred'
import { getBook, removeBook } from '#/lib/book-functions'
import { discoverBook } from '#/lib/discover-functions'
import { revertMatch } from '#/lib/match-functions'
import { languageName } from '#/lib/utils'

export const Route = createFileRoute('/_app/books/$bookId')({
  loader: async ({ params }) => {
    const book = await getBook({ data: params.bookId })
    if (!book) throw notFound()
    return book
  },
  head: ({ loaderData }) => ({
    meta: loaderData ? [{ title: `${loaderData.title} · Bookserve` }] : [],
  }),
  component: Book,
})

function Book() {
  const book = Route.useLoaderData()
  const { user } = Route.useRouteContext()
  const discovery = useDeferred(book.id, () => discoverBook({ data: book.id }))
  const series = book.series
    ? { name: book.series, position: book.seriesIndex }
    : discovery?.series
  const details = [
    ['Publisher', book.publisher],
    ['Published', book.publishedDate],
    ['ISBN', book.isbn],
    ['Language', book.language && languageName(book.language)],
    ['Pages', book.pageCount && String(book.pageCount)],
  ].filter((entry): entry is [string, string] => Boolean(entry[1]))

  return (
    <main className="mx-auto grid max-w-6xl gap-8 px-4 py-8 sm:grid-cols-[14rem_1fr] md:grid-cols-[16rem_1fr]">
      <BookCover {...book} className="mx-auto max-w-56 sm:max-w-none" />
      <div className="min-w-0">
        <h1 className="text-2xl font-semibold text-balance">{book.title}</h1>
        {book.authors.length > 0 && (
          <p className="mt-1 text-lg text-muted-foreground">
            {book.authors.map((author, i) => (
              <Fragment key={author}>
                {i > 0 && ', '}
                <Link
                  to="/authors/$name"
                  params={{ name: author }}
                  className="hover:text-foreground hover:underline"
                >
                  {author}
                </Link>
              </Fragment>
            ))}
          </p>
        )}
        {series && (
          <p className="mt-2 text-sm">
            <Link
              to="/series/$name"
              params={{ name: series.name }}
              search={{ author: book.authors[0] }}
              className="hover:underline"
            >
              {series.name}
              {series.position != null && ` #${series.position}`}
            </Link>
          </p>
        )}
        {discovery && (
          <div className="mt-3 flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
            {discovery.rating != null && (
              <a
                href={discovery.url}
                target="_blank"
                rel="noreferrer"
                className="mr-1 flex items-center gap-1 hover:text-foreground"
              >
                <Star className="size-3.5 fill-current" />
                {discovery.rating.toFixed(1)} on Hardcover
              </a>
            )}
            {[...discovery.genres, ...discovery.moods].map((tag) => (
              <span
                key={tag}
                className="rounded-full border px-2 py-0.5 text-xs"
              >
                {tag}
              </span>
            ))}
          </div>
        )}
        {book.progress && (
          <div className="mt-6 max-w-sm">
            <div className="flex justify-between text-sm">
              <span className="font-medium">
                {Math.round(book.progress.percentage * 100)}%
              </span>
              <span className="text-muted-foreground">
                {book.progress.device} · {book.progress.updatedAt.slice(0, 10)}
              </span>
            </div>
            <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-muted">
              <div
                className="h-full rounded-full bg-primary"
                style={{ width: `${book.progress.percentage * 100}%` }}
              />
            </div>
          </div>
        )}
        <div className="mt-6 flex flex-wrap gap-3">
          {book.missing ? (
            <Button disabled>File missing</Button>
          ) : (
            <Button asChild>
              <a href={`/api/books/${book.id}/download`} download>
                <Download />
                Download
              </a>
            </Button>
          )}
          {user.role === 'admin' && <AdminActions book={book} />}
        </div>
        {book.description && (
          <p className="mt-8 max-w-prose text-sm leading-relaxed whitespace-pre-line">
            {book.description}
          </p>
        )}
        {details.length > 0 && (
          <dl className="mt-8 grid grid-cols-[auto_1fr] gap-x-6 gap-y-2 text-sm">
            {details.map(([label, value]) => (
              <div key={label} className="contents">
                <dt className="text-muted-foreground">{label}</dt>
                <dd>{value}</dd>
              </div>
            ))}
          </dl>
        )}
        {discovery && (
          <div className="mt-10 grid gap-8">
            {discovery.moreByAuthor && (
              <DiscoverRow
                title={`More by ${discovery.moreByAuthor.name}`}
                books={discovery.moreByAuthor.books}
                admin={user.role === 'admin'}
              />
            )}
            <DiscoverRow
              title="Similar books"
              books={discovery.similar}
              admin={user.role === 'admin'}
            />
          </div>
        )}
      </div>
    </main>
  )
}

function AdminActions({
  book,
}: {
  book: ReturnType<typeof Route.useLoaderData>
}) {
  const router = useRouter()
  const [matching, setMatching] = useState(false)
  const [pending, setPending] = useState(false)
  const [error, setError] = useState('')

  // Click handler for a confirm button. Keeps the dialog open until the request
  // finishes so errors show inline.
  const confirm = (action: () => Promise<unknown>) =>
    async function (event: React.MouseEvent) {
      event.preventDefault()
      setPending(true)
      setError('')
      try {
        await action()
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Request failed')
      } finally {
        setPending(false)
      }
    }

  const revert = confirm(async () => {
    await revertMatch({ data: book.id })
    await router.invalidate()
  })

  const remove = confirm(async () => {
    await removeBook({ data: book.id })
    await router.navigate({ to: '/' })
  })

  return (
    <>
      <Button variant="outline" onClick={() => setMatching(true)}>
        <SearchCheck />
        Match
      </Button>
      <MatchDialog book={book} open={matching} onOpenChange={setMatching} />
      {book.matched && (
        <AlertDialog onOpenChange={() => setError('')}>
          <AlertDialogTrigger asChild>
            <Button variant="ghost">
              <RotateCcw />
              Revert to file metadata
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Revert to file metadata?</AlertDialogTitle>
            </AlertDialogHeader>
            {error && <p className="text-sm text-destructive">{error}</p>}
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction onClick={revert} disabled={pending}>
                Revert
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
      <AlertDialog onOpenChange={() => setError('')}>
        <AlertDialogTrigger asChild>
          <Button variant="ghost" className="text-destructive">
            <Trash2 />
            Delete
          </Button>
        </AlertDialogTrigger>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {book.title}?</AlertDialogTitle>
            <AlertDialogDescription>
              {book.missing
                ? 'The book will be removed from the library.'
                : 'The book file will be permanently deleted from disk.'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          {error && <p className="text-sm text-destructive">{error}</p>}
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={remove}
              disabled={pending}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
